import {bindProductDrag} from './product-media.js';
import { productVisibleForPostal } from './delivery-context.js';
import { readMarketplace } from './marketplace-settings.js';
import { renderConfiguredModules, bindConfiguredCarousels } from './configured-modules.js';
// Composição demonstrativa de módulos. Os destinos usam o catálogo local.
export function mountMerchandising({products,categories,icon,card,state,render}) {
  const subcategories = [
    [['Poltronas','Poltrona'],['Cadeiras','Cadeira'],['Iluminação','Luminária']],
    [['Tênis casuais','Tênis casual'],['Bolsas','Bolsa'],['Óculos de sol','Óculos']],
    [['Kits de cuidados','Kit'],['Cuidados diários','cuidados']],
    [['Áudio e fones','Fone'],['Câmeras','Câmera']],
    [['Tênis esportivos','Tênis esportivo'],['Caminhada','caminhada']],
    [['Vasos e folhagens','Vaso'],['Cuidados com o jardim','Kit para cuidar']],
    [['E-books','E-book'],['Guias digitais','Guia']]
  ];
  const nav=document.querySelector('.nav');
  nav.innerHTML=`<div class="wrap menu-bar"><button class="all menu-trigger" data-menu="all" aria-expanded="false" aria-controls="category-panel">${icon('menu')} Todas as categorias ${icon('chevron')}</button>${categories.map(([c],i)=>`<button class="menu-trigger" data-menu="${i}" aria-expanded="false" aria-controls="category-panel">${c}${icon('chevron')}</button>`).join('')}</div><div class="wrap mega-anchor"><section id="category-panel" class="mega-menu" aria-label="Subcategorias" hidden></section></div>`;
  const panel=nav.querySelector('#category-panel');
  let current=null;
  function closeMenu(focus=false){const trigger=nav.querySelector('[aria-expanded="true"]');panel.hidden=true;nav.querySelectorAll('.menu-trigger').forEach(x=>x.setAttribute('aria-expanded','false'));current=null;if(focus)trigger?.focus();}
  const imageLink=(p,title,category=false)=>!productVisibleForPostal(p)?'':`<button class="menu-image" data-action="${category?'category':'product'}" ${category?`data-category="${p.category}"`:`data-id="${p.id}"`}><img src="${p.image}" alt="" loading="lazy"><span><small>${category?'EXPLORE A CATEGORIA':'PRODUTO EM DESTAQUE'}</small><b>${title}</b><i>${category?'Ver seleção':'Conhecer produto'} ${icon('arrow')}</i></span></button>`;
  function openMenu(key){current=key;nav.querySelectorAll('.menu-trigger').forEach(x=>x.setAttribute('aria-expanded',String(x.dataset.menu===key)));const ids=key==='all'?categories.map((_,i)=>i):[Number(key)];const index=key==='all'?0:Number(key);const featured=products.filter(p=>productVisibleForPostal(p)&&p.category===categories[index][0]);panel.innerHTML=`<div class="mega-top"><b>${key==='all'?'Explore por categoria':categories[index][0]}</b><button class="close" data-close-menu aria-label="Fechar submenus">${icon('close')}</button></div><div class="mega-content"><div class="mega-links ${key==='all'?'all-categories':''}">${ids.map(i=>`<div class="subcategory-group"><button class="category-heading" data-action="category" data-category="${categories[i][0]}">${icon(categories[i][1])}${categories[i][0]} ${icon('arrow')}</button>${subcategories[i].map(([label,q])=>`<button data-subcategory="${q}" data-parent="${categories[i][0]}">${label}</button>`).join('')}</div>`).join('')}</div><div class="mega-images">${imageLink(featured[0],featured[0]?.name)}${imageLink(featured.at(-1),'Mais em '+categories[index][0].toLowerCase(),true)}</div></div>`;panel.hidden=false;}
  nav.addEventListener('click',e=>{const trigger=e.target.closest('[data-menu]');if(trigger){current===trigger.dataset.menu?closeMenu():openMenu(trigger.dataset.menu);return}if(e.target.closest('[data-close-menu]')){closeMenu(true);return}const sub=e.target.closest('[data-subcategory]');if(sub){state.category=sub.dataset.parent;state.query=sub.dataset.subcategory;state.store=null;state.view='all';state.status='ready';render();document.querySelector('#produtos').scrollIntoView();return}if(e.target.closest('[data-action]'))closeMenu();});
  nav.addEventListener('keydown',e=>{if(e.key==='Escape'){closeMenu(true);e.preventDefault()}if(e.key==='ArrowDown'&&e.target.matches('[data-menu]')){openMenu(e.target.dataset.menu);panel.querySelector('button')?.focus();e.preventDefault()}});
  // Replaced on rerender to avoid accumulating global listeners.
  document.onpointerdown=e=>{if(!nav.contains(e.target))closeMenu()};
  nav.addEventListener('focusout',e=>{if(e.relatedTarget&&!nav.contains(e.relatedTarget))closeMenu()});
  const controls=id=>`<div class="carousel-controls"><button data-carousel="${id}" data-direction="-1" aria-label="Produtos anteriores" disabled>${icon('arrow')}</button><button data-carousel="${id}" data-direction="1" aria-label="Próximos produtos">${icon('arrow')}</button></div>`;
  const grid=document.querySelector('#product-grid');grid.classList.add('carousel-track');grid.tabIndex=0;grid.setAttribute('aria-label','Descobertas para você — carrossel de produtos');
  document.querySelector('#produtos .section-head').insertAdjacentHTML('beforeend',controls('product-grid'));
  const banner=({cls='',eyebrow,title,cta,p,category})=>!productVisibleForPostal(p)?'':`<button class="campaign ${cls}" data-action="${category?'category':'product'}" ${category?`data-category="${category}"`:`data-id="${p.id}"`}><img src="${p.image}" alt="" loading="lazy"><span class="campaign-copy"><small>${eyebrow}</small><strong>${title}</strong><span class="campaign-cta">${cta} ${icon('arrow')}</span></span></button>`;
  const showcase=(id,title,subtitle,list)=>!list.some(p=>productVisibleForPostal(p))?'':`<section class="section product-showcase" aria-labelledby="${id}-title"><div class="section-head"><div><h2 id="${id}-title">${title}</h2><p>${subtitle}</p></div>${controls(id)}</div><div class="products carousel-track" id="${id}" tabindex="0" aria-label="${title} — carrossel de produtos">${list.map(card).join('')}</div></section>`;
  const mosaic=`<section class="section" aria-labelledby="mosaic-title"><div class="section-head"><div><h2 id="mosaic-title">Encontre seu próximo favorito</h2><p>Uma seleção de ideias para a casa, a rotina e você.</p></div></div><div class="banner-mosaic">${banner({cls:'mosaic-tall',eyebrow:'SEU ESTILO',title:'Detalhes que<br>fazem você.',cta:'Explorar acessórios',p:products[4],category:categories[1][0]})}${banner({cls:'mosaic-main',eyebrow:'VIVER BEM, BEM PERTO',title:'Dê um novo olhar<br>para sua casa.',cta:'Descobrir casa & decoração',p:products[0],category:categories[0][0]})}${banner({cls:'mosaic-small tech-banner',eyebrow:'CONECTE-SE',title:'Sua trilha.<br>Seu momento.',cta:'Conhecer o fone',p:products[2]})}${banner({cls:'mosaic-small plant-banner',eyebrow:'RESPIRE NOVO',title:'Mais verde<br>no seu dia.',cta:'Explorar plantas',p:products[3],category:categories[5][0]})}</div></section>`;
  const homeProducts=products.filter(p=>[0,3,7,9,11,6].includes(p.id));
  const routineProducts=products.filter(p=>[1,2,4,5,6,8,10].includes(p.id));
  document.querySelector('#produtos').insertAdjacentHTML('afterend',mosaic+showcase('home-selection','Pequenos detalhes, novos ares','Ideias para deixar cada canto com a sua cara.',homeProducts)+`<section class="section banner-pair" aria-label="Seleções para sua rotina">${banner({cls:'wide-banner style-banner',eyebrow:'ENCONTRE SEU RITMO',title:'Conforto para<br>acompanhar você.',cta:'Ver esporte & lazer',p:products[8],category:categories[4][0]})}${banner({cls:'wide-banner care-banner',eyebrow:'UM TEMPO PARA VOCÊ',title:'Sua rotina merece<br>esse cuidado.',cta:'Explorar beleza & cuidados',p:products[6],category:categories[2][0]})}</section>`+showcase('routine-selection','Escolhas para o seu dia a dia','Tecnologia, estilo e cuidados das lojas da região.',routineProducts)+`<section class="section"><div class="editorial-strip"><div>${icon('store')}<span>BOAS DESCOBERTAS COMEÇAM PERTO</span></div><h2>Conheça as lojas por trás<br>dos seus próximos favoritos.</h2><a class="btn" href="#lojas">Explorar lojas locais ${icon('arrow')}</a></div></section>`);
  document.querySelectorAll('.banner-mosaic,.banner-pair').forEach(el=>{if(!el.children.length)el.closest('section')?.remove()});
  const config=readMarketplace();if(config.modules.length){let next=document.querySelector('#produtos').nextElementSibling;while(next&&!next.matches('#lojas')){const following=next.nextElementSibling;next.remove();next=following;}document.querySelector('#produtos').hidden=true;document.querySelector('#produtos').insertAdjacentHTML('afterend',renderConfiguredModules(config.modules,products,card,v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))));bindConfiguredCarousels();}
  document.querySelectorAll('.carousel-track').forEach(track=>{bindProductDrag(track);
    const buttons=[...document.querySelectorAll(`[data-carousel="${track.id}"]`)];
    const update=()=>buttons.forEach(b=>b.disabled=Number(b.dataset.direction)<0?track.scrollLeft<=2:track.scrollLeft+track.clientWidth>=track.scrollWidth-3);
    const move=direction=>{const first=track.querySelector('.product');const step=first?first.getBoundingClientRect().width+parseFloat(getComputedStyle(track).columnGap):track.clientWidth;track.scrollBy({left:direction*step*Math.max(1,Math.round((track.clientWidth+parseFloat(getComputedStyle(track).columnGap))/step)),behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'})};
    buttons.forEach(b=>b.addEventListener('click',()=>move(Number(b.dataset.direction))));
    track.addEventListener('scroll',update,{passive:true});track.addEventListener('keydown',e=>{if(e.target===track&&['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();move(e.key==='ArrowLeft'?-1:1)}});
    const observer=new ResizeObserver(update);observer.observe(track);
    const mutation=new MutationObserver(update);mutation.observe(track,{childList:true});
    // Clean up when a new application render replaces the tracks.
    track._cleanup=()=>{observer.disconnect();mutation.disconnect()};update();
  });
}
